Console.WriteLine("=== COMPILER INVOCATIONS ===");
build.VisitAllChildren<Task>(task => {
    if (task.Name == "Csc") {
        var proj = task.GetNearestParent<Project>();
        Console.WriteLine($"\nProject: {proj?.Name}");
        Console.WriteLine($"  CommandLine: {task.CommandLineArguments?.Substring(0, Math.Min(500, task.CommandLineArguments?.Length ?? 0))}");
    }
});

